/* Message sent at the beginning of each connection
 Can only be sent by the client and only at the beginning of the connection */
typedef struct _HelloRequest {
    /* Description of client (like User Agent)
 For example "Home Assistant"
 Not strictly necessary to send but nice for debugging
 purposes. */
    char *client_info;
    uint32_t api_version_major;
    uint32_t api_version_minor;
    /* Set by clients that can accept connections the device opens to them
 (see api: outgoing_connection:). The device remembers this client's
 address as the target to dial when no such client is connected. */
    bool outgoing_connection_target;
} HelloRequest;

/* Confirmation of successful connection request.
 Can only be sent by the server and only at the beginning of the connection */
typedef struct _HelloResponse {
    /* The version of the API to use. The _client_ (for example Home Assistant) needs to check
 for compatibility and if necessary adopt to an older API.
 Major is for breaking changes in the base protocol - a mismatch will lead to immediate disconnect_client_
 Minor is for breaking changes in individual messages - a mismatch will lead to a warning message */
    uint32_t api_version_major;
    uint32_t api_version_minor;
    /* A string identifying the server (ESP); like client info this may be empty
 and only exists for debugging/logging purposes.
 Currently set to ESPHOME_VERSION string literal. */
    char *server_info;
    /* The name of the server (App.get_name() - device hostname)
 max_data_length matches ESPHOME_DEVICE_NAME_MAX_LEN (validated by validate_hostname) */
    char *name;
} HelloResponse;

