/* Command to transmit infrared/RF data using raw timings */
typedef struct _InfraredRFTransmitRawTimingsRequest {
    uint32_t device_id;
    uint32_t key; /* Key identifying the transmitter instance */
    uint32_t carrier_frequency; /* Carrier frequency in Hz */
    uint32_t repeat_count; /* Number of times to transmit (1 = once, 2 = twice, etc.) */
    pb_size_t timings_count;
    int32_t *timings; /* Raw timings in microseconds (zigzag-encoded): positive = mark (LED/TX on), negative = space (LED/TX off) */
    uint32_t modulation; /* RadioFrequencyModulation enum value (0 = OOK; ignored for IR entities) */
} InfraredRFTransmitRawTimingsRequest;

/* Event message for received infrared/RF data */
typedef struct _InfraredRFReceiveEvent {
    uint32_t device_id;
    uint32_t key; /* Key identifying the receiver instance */
    pb_size_t timings_count;
    int32_t *timings; /* Raw timings in microseconds (zigzag-encoded): alternating mark/space periods */
} InfraredRFReceiveEvent;

/* Sent only to the client that issued an InfraredRFTransmitRawTimingsRequest, once the
 transmitter reports that the transmission (all repeats) has finished, or immediately with
 success=false if it was refused before reaching the transmitter (unknown key, no transmitter,
 no or invalid timings) or the transmitter could not send it (not set up, hardware error).
 success=false also answers a request superseded by a newer request on the same entity, from
 any client, and a transmit that reported nothing within 30 s past its expected air time, so a
 client should not retry on it blindly. The device serializes transmits per transmitter and
 several entities may share one, so a client should keep at most one transmit outstanding per
 device, not per entity. A reply for an unknown key or a refused request is sent once and can be lost
 when the device's send buffer is full, so a client should also stop waiting on its own after the
 expected air time plus a margin. Lets clients pace requests instead of estimating durations (since API 1.18) */
typedef struct _InfraredRFTransmitCompleteResponse {
    uint32_t device_id;
    uint32_t key; /* Key of the transmitter entity from the request */
    bool success; /* false if the request was refused, not sent, superseded, or never reported */
} InfraredRFTransmitCompleteResponse;

/* Lists available radio frequency entity instances */
typedef struct _ListEntitiesRadioFrequencyResponse {
    char *object_id;
    uint32_t key;
    char *name;
    char *icon;
    bool disabled_by_default;
    EntityCategory entity_category;
    uint32_t device_id;
    uint32_t capabilities; /* Bitmask of RadioFrequencyCapabilityFlags: bit 0 = transmitter, bit 1 = receiver */
    uint32_t frequency_min; /* Minimum tunable frequency in Hz; if min == max (non-zero): fixed frequency; 0 = unspecified */
    uint32_t frequency_max; /* Maximum tunable frequency in Hz; 0 = unspecified */
    uint32_t supported_modulations; /* Bitmask of supported RadioFrequencyModulation values (bit N = modulation N supported) */
} ListEntitiesRadioFrequencyResponse;

/* Configure UART parameters for a serial proxy instance. Only the subscribed client may
 configure the port; others are refused with PORT_IN_USE (since API 1.17). */
typedef struct _SerialProxyConfigureRequest {
    uint32_t instance; /* Instance index (0-based) */
    uint32_t baudrate; /* Baud rate in bits per second */
    bool flow_control; /* Enable hardware flow control */
    SerialProxyParity parity; /* Parity setting */
    uint32_t stop_bits; /* Number of stop bits (1 or 2) */
    uint32_t data_size; /* Number of data bits (5-8) */
} SerialProxyConfigureRequest;

/* Data received from a serial device, forwarded to clients */
typedef struct _SerialProxyDataReceived {
    uint32_t instance; /* Instance index (0-based) */
    pb_bytes_array_t *data; /* Raw data received from the serial device */
} SerialProxyDataReceived;

/* Write data to a serial device. Only the subscribed client may write; writes from
 others are ignored (since API 1.17). */
typedef struct _SerialProxyWriteRequest {
    uint32_t instance; /* Instance index (0-based) */
    pb_bytes_array_t *data; /* Raw data to write to the serial device */
} SerialProxyWriteRequest;

/* Set modem control pin states (RTS and DTR). Only the subscribed client may set them;
 others are refused with PORT_IN_USE (since API 1.17). */
typedef struct _SerialProxySetModemPinsRequest {
    uint32_t instance; /* Instance index (0-based) */
    uint32_t line_states; /* Bitmask of SerialProxyLineStateFlags */
} SerialProxySetModemPinsRequest;

/* Request current modem control pin states */
typedef struct _SerialProxyGetModemPinsRequest {
    uint32_t instance; /* Instance index (0-based) */
} SerialProxyGetModemPinsRequest;

/* Response with current modem control pin states */
typedef struct _SerialProxyGetModemPinsResponse {
    uint32_t instance; /* Instance index (0-based) */
    uint32_t line_states; /* Bitmask of SerialProxyLineStateFlags */
    SerialProxyStatus status; /* INVALID_ARGUMENT if the instance index is out of range (since API 1.16) */
} SerialProxyGetModemPinsResponse;

/* Generic request message for simple serial proxy operations. FLUSH requires an active
 subscription; it is refused with PORT_IN_USE otherwise (since API 1.17). */
typedef struct _SerialProxyRequest {
    uint32_t instance; /* Instance index (0-based) */
    SerialProxyRequestType type; /* Request type */
} SerialProxyRequest;

/* Acknowledges a serial proxy operation; the type field identifies which
 operation is being acknowledged. Flush has been acknowledged since the
 message was introduced; all other acknowledgements are sent since API 1.16. */
typedef struct _SerialProxyRequestResponse {
    uint32_t instance; /* Instance index (0-based) */
    SerialProxyRequestType type; /* Which request type this responds to */
    SerialProxyStatus status; /* Result status */
    char *error_message; /* Additional detail on failure (optional) */
} SerialProxyRequestResponse;

/* Only the subscribed client may change the mode; any other caller -- including one that
 never subscribed -- is refused with PORT_IN_USE. PROTOCOL is refused with NOT_SUPPORTED
 when the port has no protocol-aware tap configured. */
typedef struct _SerialProxySetModeRequest {
    uint32_t instance;
    SerialProxyMode mode;
} SerialProxySetModeRequest;

/* Subscribe to the identity of every serial proxy port. The device answers with one
 SerialProxyIdentity per port, then sends another whenever a port's identity changes,
 for the life of the connection (since API 1.18). */
typedef struct _SubscribeSerialProxyIdentityRequest {
    char dummy_field;
} SubscribeSerialProxyIdentityRequest;

/* The descriptor fields of a USB device as seen by the host stack, and the port's index
 among those a vendor driver exposes on the interface */
typedef struct _UsbDeviceDescriptor {
    uint32_t vendor_id;
    uint32_t product_id;
    uint32_t bcd_device;
    uint32_t interface_number; /* bInterfaceNumber the port is bound through */
    uint32_t interface_class; /* bInterfaceClass of that interface */
    uint32_t port_number;
    char *interface_description; /* iInterface string of that interface, empty when it has none */
} UsbDeviceDescriptor;

/* The identity of the device behind a port. Identifies one physical device among others of
 the same kind, so a client matches on manufacturer and product regardless of source. The
 strings are empty for source NONE, and for source USB while nothing is connected
 (since API 1.18). */
typedef struct _SerialProxyIdentity {
    uint32_t instance;
    SerialProxyIdentitySource source;
    uint32_t flags; /* Bitmask of SerialProxyIdentityFlag */
    char *manufacturer;
    char *product;
    char *serial_number;
    bool has_usb;
    UsbDeviceDescriptor usb; /* Only sent for source USB */
} SerialProxyIdentity;

/* ==================== BLUETOOTH CONNECTION PARAMS ==================== */
typedef struct _BluetoothSetConnectionParamsRequest {
    uint64_t address;
    uint32_t min_interval; /* units of 1.25ms */
    uint32_t max_interval; /* units of 1.25ms */
    uint32_t latency;
    uint32_t timeout; /* units of 10ms */
} BluetoothSetConnectionParamsRequest;

typedef struct _BluetoothSetConnectionParamsResponse {
    uint64_t address;
    int32_t error;
} BluetoothSetConnectionParamsResponse;

/* Requests the Sendspin pairing token, which a Sendspin server uses to pair with this device */
typedef struct _SendspinPairingTokenRequest {
    char dummy_field;
} SendspinPairingTokenRequest;

typedef struct _SendspinPairingTokenResponse {
    SendspinPairingTokenStatus status;
    /* The pairing token (Sendspin pairing.md "Pairing Token"). Set only when status is OK. */
    char *token;
} SendspinPairingTokenResponse;

/* ==================== STORE YAML ====================
 Streams the compressed user YAML embedded in firmware; the client decompresses.
 A GetYamlRequest during an active transfer is ignored; reconnect to restart. */
typedef struct _GetYamlRequest {
    char dummy_field;
} GetYamlRequest;

typedef struct _GetYamlResponse {
    /* A zstd frame of the EHY1 file envelope, sent from flash */
    pb_bytes_array_t *data;
    bool done;
    /* Set on the first chunk only */
    uint32_t total_size;
} GetYamlResponse;


